solutionQuery:
SELECT PRODUCT_NAME, UNIT_PRICE
FROM PRODUCTS
WHERE CATEGORY = 'Books';

SELECT COUNT(*) AS OPEN_TICKET_COUNT
FROM SUPPORT_TICKETS
WHERE STATUS = 'OPEN';

SELECT CUSTOMERS.CUSTOMER_NAME, ORDERS.ORDER_TOTAL
FROM ORDERS
INNER JOIN CUSTOMERS ON ORDERS.CUSTOMER_ID = CUSTOMERS.CUSTOMER_ID;

SELECT TEAMS.TEAM_NAME, PROJECTS.PROJECT_TITLE
FROM TEAMS
LEFT JOIN PROJECTS ON TEAMS.TEAM_ID = PROJECTS.TEAM_ID;

SELECT *
FROM USERS
WHERE EMAIL LIKE '%@example.org';
